export const code = async (inputs) => {
  const lead = inputs.lead || {};
  const data = lead.data || {};
  const pick = (...keys) => {
    for (const key of keys) {
      const value = data[key];
      const text = Array.isArray(value) ? value.join(', ') : String(value ?? '').trim();
      if (text !== '') {
        return text.slice(0, 200);
      }
    }
    return '';
  };
  const email = pick('email', 'work_email').toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    throw new Error('Lead ' + String(lead.lead_id ?? '?') + ' has no valid email - add an email question to the form or handle it by hand');
  }
  const fullName = pick('full_name');
  const parts = fullName.split(/\s+/).filter(Boolean);
  const firstName = pick('first_name') || parts[0] || '';
  const lastName = pick('last_name') || parts.slice(1).join(' ');
  const known = ['email', 'work_email', 'full_name', 'first_name', 'last_name', 'phone_number'];
  const answers = Object.keys(data).filter((key) => !known.includes(key))
    .map((key) => key + ': ' + pick(key)).join('\n');
  return {
    email,
    firstName,
    lastName,
    name: [firstName, lastName].filter(Boolean).join(' ') || email,
    phone: pick('phone_number', 'phone'),
    campaign: String(lead.campaign_name ?? ''),
    ad: String(lead.ad_name ?? ''),
    submittedAt: String(lead.created_time ?? ''),
    answers,
  };
};

